1	import type { Dispatch, SetStateAction, TransitionStartFunction } from "react";
2	import { getCommits } from "../actions";
3	import type { CommitData } from "../commitTypes";
4	import { getUsernameValidationMessage, normalizeGitHubUsername } from "../username";
5	import { trackAppEvent } from "./analytics";
6	import { MAX_RECENT_SEARCHES } from "./constants";
7	import { saveStoredRecentSearches } from "./recentSearches";
8	import { updateSharedSearchUrl } from "./sharedSearch";
9	
10	type SearchHandlers = {
11	  isLatestSearch: () => boolean;
12	  startTransition: TransitionStartFunction;
13	  setLastSearchedUsername: Dispatch<SetStateAction<string>>;
14	  setShareStatus: Dispatch<SetStateAction<string>>;
15	  setResult: Dispatch<SetStateAction<CommitData | null>>;
16	  setRecentSearches: Dispatch<SetStateAction<string[]>>;
17	};
18	
19	function unexpectedSearchError(): CommitData {
20	  return {
21	    found: false,
22	    error: "GitHub commit search failed. Please try again.",
23	    errorKind: "unknown",
24	    commits: [],
25	  };
26	}
27	
28	export function runCommitSearch(
29	  searchUsername: string,
30	  options: { updateUrl?: boolean } = {},
31	  {
32	    isLatestSearch,
33	    startTransition,
34	    setLastSearchedUsername,
35	    setShareStatus,
36	    setResult,
37	    setRecentSearches,
38	  }: SearchHandlers,
39	) {
40	  const trimmedUsername = normalizeGitHubUsername(searchUsername);
41	  if (!trimmedUsername) return;
42	  if (getUsernameValidationMessage(trimmedUsername)) return;
43	  if (options.updateUrl) updateSharedSearchUrl(trimmedUsername);
44	
45	  trackAppEvent("search_submitted", {
46	    source: options.updateUrl ? "user" : "shared_url",
47	  });
48	  setLastSearchedUsername(trimmedUsername);
49	  setShareStatus("");
50	  startTransition(async () => {
51	    let data: CommitData;
52	    try {
53	      data = await getCommits(trimmedUsername);
54	    } catch {
55	      data = unexpectedSearchError();
56	    }
57	    if (!isLatestSearch()) return;
58	
59	    setResult(data);
60	    trackAppEvent("search_completed", {
61	      found: data.found,
62	      error_kind: data.errorKind ?? "none",
63	      commit_count: data.commits.length,
64	    });
65	    if (data.found) {
66	      setRecentSearches((currentSearches) => {
67	        const nextSearches = [
68	          trimmedUsername,
69	          ...currentSearches.filter(
70	            (search) => search.toLowerCase() !== trimmedUsername.toLowerCase(),
71	          ),
72	        ].slice(0, MAX_RECENT_SEARCHES);
73	
74	        saveStoredRecentSearches(nextSearches);
75	        return nextSearches;
76	      });
77	    }
78	  });
